import type { Telemetry, TelemetryProperties, TelemetryContext } from '../types'
import { describeError } from './util'

const CAPTURE_PATH = '/i/v0/e/'
const DB_NAME = 'now-sdk-telemetry'
const STORE_NAME = 'ids'
const ID_KEY = 'now_sdk_telemetry_id'

// `localStorage` doesn't exist in a Web Worker (this client also runs in Glider's extension-host
// worker), but IndexedDB does and offers the same per-browser-profile persistence, so it's used
// to persist the anonymous distinct_id across separate client instantiations/sessions.
function idbRequest<T>(request: IDBRequest<T>): Promise<T> {
    return new Promise((resolve, reject) => {
        request.onsuccess = () => resolve(request.result)
        request.onerror = () => reject(request.error)
    })
}

function openDb(): Promise<IDBDatabase> {
    const request = indexedDB.open(DB_NAME, 1)
    request.onupgradeneeded = () => request.result.createObjectStore(STORE_NAME)
    return idbRequest(request)
}

function idbGet(db: IDBDatabase, key: string): Promise<string | undefined> {
    return idbRequest(db.transaction(STORE_NAME, 'readonly').objectStore(STORE_NAME).get(key))
}

function idbSet(db: IDBDatabase, key: string, value: string): Promise<void> {
    return idbRequest(db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).put(value, key)).then(
        () => undefined
    )
}

export type PostHogBrowserClientOptions = {
    apiKey: string
    host: string
    sdkVersion?: string | undefined
    clientName?: 'CLI' | 'IDE' | (string & {}) | undefined
    ideVersion?: string | undefined
    hostname?: string | undefined
    codingAgent?: string | undefined
}

// Uses fetch() directly against PostHog's HTTP capture API instead of posthog-js, since this
// client also runs inside VS Code web-extension webworkers, where `window`/`document` (and thus
// posthog-js) are unavailable but fetch is.
export class PostHogBrowserClient implements Telemetry {
    private readonly config: { apiKey: string; host: string }
    private readonly context: TelemetryContext
    private readonly pending = new Set<Promise<void>>()
    private distinctIdPromise?: Promise<string>

    constructor(options: PostHogBrowserClientOptions) {
        this.config = { apiKey: options.apiKey, host: options.host }
        this.context = this.buildContext(options)
    }

    capture(event: string, properties?: TelemetryProperties): void {
        const send = this.sendEvent(event, properties).catch(() => {})
        this.pending.add(send)
        void send.finally(() => this.pending.delete(send))
    }

    captureError(event: string, error: unknown, properties?: TelemetryProperties): void {
        const { category, fingerprint, message } = describeError(error)
        this.capture(event, {
            success: false,
            error_category: category,
            error_fingerprint: fingerprint,
            error_message: message,
            ...properties,
        })
    }

    async flush(): Promise<void> {
        await Promise.all(this.pending)
    }

    async shutdown(): Promise<void> {
        await this.flush()
    }

    private async sendEvent(event: string, properties?: TelemetryProperties): Promise<void> {
        const distinctId = await this.getDistinctId()
        await fetch(`${this.config.host}${CAPTURE_PATH}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                api_key: this.config.apiKey,
                event,
                properties: {
                    distinct_id: distinctId,
                    ...this.context,
                    ...properties,
                    $geoip_disable: true,
                },
                timestamp: new Date().toISOString(),
            }),
        })
    }

    private buildContext(options: PostHogBrowserClientOptions): TelemetryContext {
        const context: TelemetryContext = {
            sdkVersion: options.sdkVersion ?? 'unknown',
            clientName: options.clientName ?? 'IDE',
            isCI: false,
        }

        if (options.ideVersion) {
            context.ideVersion = options.ideVersion
        }

        if (options.hostname) {
            context.hostname = options.hostname
        }

        if (options.codingAgent) {
            context.codingAgent = options.codingAgent
        }

        return context
    }

    private getDistinctId(): Promise<string> {
        if (!this.distinctIdPromise) {
            this.distinctIdPromise = this.resolveAnonymousId()
        }
        return this.distinctIdPromise
    }

    private async resolveAnonymousId(): Promise<string> {
        try {
            const db = await openDb()
            const existing = await idbGet(db, ID_KEY)
            if (existing) {
                return existing
            }
            const id = crypto.randomUUID()
            await idbSet(db, ID_KEY, id)
            return id
        } catch {
            return `temp_${Date.now()}_${Math.random().toString(36).slice(2)}`
        }
    }
}
